const updateContest = `-- name: UpdateContest :exec
UPDATE contests
SET login = COALESCE($2, login),
    title = COALESCE($3, title),
    place = COALESCE($4, place),
    description = COALESCE($5, description),
    visibility = COALESCE($6, visibility),
    join_policy = COALESCE($7, join_policy),
    scoreboard_during = COALESCE($8, scoreboard_during),
    scoreboard_after = COALESCE($9, scoreboard_after),
    submissions_during = COALESCE($10, submissions_during),
    submissions_after = COALESCE($11, submissions_after),
    sources_during = COALESCE($12, sources_during),
    sources_after = COALESCE($13, sources_after),
    reports_during = COALESCE($14, reports_during),
    reports_after = COALESCE($15, reports_after),
    feedback_during = COALESCE($16, feedback_during),
    feedback_after = COALESCE($17, feedback_after),
    freeze_status = COALESCE($18, freeze_status),
    freeze_duration_minutes = CASE WHEN $19::boolean THEN $20::integer ELSE freeze_duration_minutes END,
    freeze_hides_attempts = COALESCE($21, freeze_hides_attempts),
    unfreeze_time = CASE WHEN $22::boolean THEN $23::timestamptz ELSE unfreeze_time END,
    hide_statements = COALESCE($24, hide_statements),
    allow_clarifications = COALESCE($25, allow_clarifications),
    enable_drafts = COALESCE($26, enable_drafts),
    enable_upsolving = COALESCE($27, enable_upsolving),
    allow_virtual = COALESCE($28, allow_virtual),
    pretests = COALESCE($29, pretests),
    languages = COALESCE($30::text[], languages),
    start_time = CASE WHEN $31::boolean THEN $32::timestamptz ELSE start_time END,
    end_time = CASE WHEN $33::boolean THEN $34::timestamptz ELSE end_time END
WHERE id = $1
`

type UpdateContestParams struct {
	ID                    uuid.UUID                        `json:"id"`
	Login                 *string                          `json:"login"`
	Title                 *string                          `json:"title"`
	Place                 *string                          `json:"place"`
	Description           *string                          `json:"description"`
	Visibility            *contestsmodel.ContestVisibility `json:"visibility"`
	JoinPolicy            *accessmodel.JoinPolicy          `json:"join_policy"`
	ScoreboardDuring      *contestsmodel.ContestScope      `json:"scoreboard_during"`
	ScoreboardAfter       *contestsmodel.ContestScope      `json:"scoreboard_after"`
	SubmissionsDuring     *contestsmodel.ContestScope      `json:"submissions_during"`
	SubmissionsAfter      *contestsmodel.ContestScope      `json:"submissions_after"`
	SourcesDuring         *contestsmodel.ContestScope      `json:"sources_during"`
	SourcesAfter          *contestsmodel.ContestScope      `json:"sources_after"`
	ReportsDuring         *contestsmodel.ContestScope      `json:"reports_during"`
	ReportsAfter          *contestsmodel.ContestScope      `json:"reports_after"`
	FeedbackDuring        *contestsmodel.FeedbackLevel     `json:"feedback_during"`
	FeedbackAfter         *contestsmodel.FeedbackLevel     `json:"feedback_after"`
	FreezeStatus          *contestsmodel.FreezeStatus      `json:"freeze_status"`
	FreezeDurationSet     bool                             `json:"freeze_duration_set"`
	FreezeDurationMinutes *int32                           `json:"freeze_duration_minutes"`
	FreezeHidesAttempts   *bool                            `json:"freeze_hides_attempts"`
	UnfreezeTimeSet       bool                             `json:"unfreeze_time_set"`
	UnfreezeTime          *time.Time                       `json:"unfreeze_time"`
	HideStatements        *bool                            `json:"hide_statements"`
	AllowClarifications   *bool                            `json:"allow_clarifications"`
	EnableDrafts          *bool                            `json:"enable_drafts"`
	EnableUpsolving       *bool                            `json:"enable_upsolving"`
	AllowVirtual          *bool                            `json:"allow_virtual"`
	Pretests              *bool                            `json:"pretests"`
	Languages             []string                         `json:"languages"`
	StartTimeSet          bool                             `json:"start_time_set"`
	StartTime             *time.Time                       `json:"start_time"`
	EndTimeSet            bool                             `json:"end_time_set"`
	EndTime               *time.Time                       `json:"end_time"`
}

func (q *Queries) UpdateContest(ctx context.Context, arg UpdateContestParams) error {
	_, err := q.db.Exec(ctx, updateContest,
		arg.ID,
		arg.Login,
		arg.Title,
		arg.Place,
		arg.Description,
		arg.Visibility,
		arg.JoinPolicy,
		arg.ScoreboardDuring,
		arg.ScoreboardAfter,
		arg.SubmissionsDuring,
		arg.SubmissionsAfter,
		arg.SourcesDuring,
		arg.SourcesAfter,
		arg.ReportsDuring,
		arg.ReportsAfter,
		arg.FeedbackDuring,
		arg.FeedbackAfter,
		arg.FreezeStatus,
		arg.FreezeDurationSet,
		arg.FreezeDurationMinutes,
		arg.FreezeHidesAttempts,
		arg.UnfreezeTimeSet,
		arg.UnfreezeTime,
		arg.HideStatements,
		arg.AllowClarifications,
		arg.EnableDrafts,
		arg.EnableUpsolving,
		arg.AllowVirtual,
		arg.Pretests,
		arg.Languages,
		arg.StartTimeSet,
		arg.StartTime,
		arg.EndTimeSet,
		arg.EndTime,
	)
	return err
}

